(1967108, 270877, 42984, '<td valign="top">Wow, what a wildlife study.  Photographically brilliant but where''s the phobia.</td>', 'Wow, what a wildlife study.  Photographically brilliant but where''s the phobia.', '2005-12-21 04:44:08.000000', NULL, 1),
(1967110, 269411, 42984, '<td valign="top">Cool phobiia and a great photograph.  This really is superb composition, light and colour.  I see the bridge, I don''t see the fear of crossing it.</td>', 'Cool phobiia and a great photograph.  This really is superb composition, light and colour.  I see the bridge, I don''t see the fear of crossing it.', '2005-12-21 04:45:40.000000', NULL, 1),
(1967111, 270611, 42984, '<td valign="top">Ooook.  I don''t know what to make of this one.  Not photographically strong but a cute story and you''ve included the fear of the object rather than most people who have simply just photographhed the object.</td>', 'Ooook.  I don''t know what to make of this one.  Not photographically strong but a cute story and you''ve included the fear of the object rather than most people who have simply just photographhed the object.', '2005-12-21 04:47:39.000000', NULL, 1),
(1967112, 269313, 42984, '<td valign="top">Gutsy, really good photographically and you have included the fear, not just the object.  The dark and light are really dramatic, you''re going to be in the ttop 20  at least I would think</td>', 'Gutsy, really good photographically and you have included the fear, not just the object.  The dark and light are really dramatic, you''re going to be in the ttop 20  at least I would think', '2005-12-21 04:49:20.000000', NULL, 1),
