(1969440, 271284, 46336, '<td valign="top">I think this shot is a bit too dark to convey all the feelings.</td>', 'I think this shot is a bit too dark to convey all the feelings.', '2005-12-21 20:32:55.000000', NULL, 1),
(1969443, 271123, 46336, '<td valign="top">First up - I''m not really getting any sense of fear or phobia from this image. Generally a positive concept in fact. What exactly are you trying to convey? <br/> <br/>Also, its a good idea to make use of the full dimensions allowed by DPC</td>', 'First up - I''m not really getting any sense of fear or phobia from this image. Generally a positive concept in fact. What exactly are you trying to convey?  Also, its a good idea to make use of the full dimensions allowed by DPC', '2005-12-21 20:36:26.000000', NULL, 1),
(1969454, 270915, 46336, '<td valign="top">The eye of the rat is eerie, but is the only way in which phobia is conveyed. This picture is too dark to adequately see the definition. The focus is too soft, and there is too much noise on the shirt.</td>', 'The eye of the rat is eerie, but is the only way in which phobia is conveyed. This picture is too dark to adequately see the definition. The focus is too soft, and there is too much noise on the shirt.', '2005-12-21 20:40:18.000000', NULL, 1),
(1969458, 271193, 46336, '<td valign="top">This picture doesn''t really convey a phobia. Indeed, I imagine the child doesn''t have a position on the subject one way or another.</td>', 'This picture doesn''t really convey a phobia. Indeed, I imagine the child doesn''t have a position on the subject one way or another.', '2005-12-21 20:42:56.000000', NULL, 1),
(1969472, 270953, 25150, '<td valign="top">Simply Amazing....</td>', 'Simply Amazing....', '2005-12-21 20:52:46.000000', NULL, 1),
(1969498, 271290, 44490, '<td valign="top">Striking image, especially with the texture and seemingly translucent skin.  Great lighting and shadows.</td>', 'Striking image, especially with the texture and seemingly translucent skin.  Great lighting and shadows.', '2005-12-21 21:05:53.000000', NULL, 1),
(1969499, 270999, 27556, '<td valign="top">theres not enough contrast in this shot for me, not much to look at</td>', 'theres not enough contrast in this shot for me, not much to look at', '2005-12-21 21:06:25.000000', NULL, 1),
(1969500, 270953, 37320, '<td valign="top">Well done, if one was too lazy too look up your phobia the picture says it all...as it should.</td>', 'Well done, if one was too lazy too look up your phobia the picture says it all...as it should.', '2005-12-21 21:06:39.000000', NULL, 1),
(1969501, 271292, 27556, '<td valign="top">great composition but too much grain</td>', 'great composition but too much grain', '2005-12-21 21:06:43.000000', NULL, 1),
(1969504, 271313, 44490, '<td valign="top">Looks like the young doctor could use improved needle technique.  The cropping seems a little too severe, but the image is effective.</td>', 'Looks like the young doctor could use improved needle technique.  The cropping seems a little too severe, but the image is effective.', '2005-12-21 21:07:01.000000', NULL, 1),
(1969508, 270217, 37320, '<td valign="top">If you were afraid of clowns before you are now, I woulda just kept the phobia naem in the title, the picture says a thousand words</td>', 'If you were afraid of clowns before you are now, I woulda just kept the phobia naem in the title, the picture says a thousand words', '2005-12-21 21:07:48.000000', NULL, 1),
