INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1969679, 271305, 49192, '<td valign="top">nice photo. good sense of height.</td>', 'nice photo. good sense of height.', '2005-12-21 22:22:40.000000', NULL, 1),
(1969681, 269967, 49192, '<td valign="top">This is cinemagraphic. looks like a still from a movie.</td>', 'This is cinemagraphic. looks like a still from a movie.', '2005-12-21 22:23:22.000000', NULL, 1),
(1969686, 270446, 49192, '<td valign="top">nice composition</td>', 'nice composition', '2005-12-21 22:23:59.000000', NULL, 1),
(1969690, 271076, 49192, '<td valign="top">nice lighting</td>', 'nice lighting', '2005-12-21 22:25:42.000000', NULL, 1),
(1969692, 270094, 49192, '<td valign="top">nice tonal range</td>', 'nice tonal range', '2005-12-21 22:27:09.000000', NULL, 1),
(1969694, 270918, 49192, '<td valign="top">pretty funny....bizarre scene</td>', 'pretty funny....bizarre scene', '2005-12-21 22:27:39.000000', NULL, 1),
(1969698, 270883, 49192, '<td valign="top">beautiful photo, you must have quick reflexes</td>', 'beautiful photo, you must have quick reflexes', '2005-12-21 22:28:30.000000', NULL, 1),
(1969699, 270408, 49192, '<td valign="top">nice composition</td>', 'nice composition', '2005-12-21 22:28:51.000000', NULL, 1),
(1969702, 270798, 49192, '<td valign="top">nice view</td>', 'nice view', '2005-12-21 22:29:30.000000', NULL, 1),
(1969781, 269548, 46336, '<td valign="top">It''s a truck driving behind you. I don''t really get a sense of fear from this image. <br/> <br/> - Composition: This is poor. The negative space (black bits above and below the subject) do not add to the image. It would have been wise to crop them out.<br/> - Focus: Nothing is directly in focus. you need to you your focal point to draw your audience in and direct their attention. <br/> - Rotate: The image would benefit from a slight (maybe 1 degree) rotation to the left.<br/> - Colour/contract: The colours are flat. This is to be expected - it is extremely difficult to photograph from a moving car in the rain. Still, you could have used levels or curves in photoshop to bring the bright colours of the truck out more.</td>', 'It''s a truck driving behind you. I don''t really get a sense of fear from this image.   - Composition: This is poor. The negative space (black bits above and below the subject) do not add to the image. It would have been wise to crop them out. - Focus: Nothing is directly in focus. you need to you your focal point to draw your audience in and direct their attention.  - Rotate: The image would benefit from a slight (maybe 1 degree) rotation to the left. - Colour/contract: The colours are flat. This is to be expected - it is extremely difficult to photograph from a moving car in the rain. Still, you could have used levels or curves in photoshop to bring the bright colours of the truck out more.', '2005-12-21 22:52:02.000000', NULL, 1),
(1969811, 270675, 42826, '<td valign="top">hahahahah too funny!!!!  That really should be a phobia!</td>', 'hahahahah too funny!!!!  That really should be a phobia!', '2005-12-21 23:06:23.000000', NULL, 1),
(1969814, 271356, 42826, '<td valign="top">nice shot...he looks a little frozen.</td>', 'nice shot...he looks a little frozen.', '2005-12-21 23:07:02.000000', NULL, 1),
(1969864, 269141, 40019, '<td valign="top">Very nicely done!  I''m feeling trapped already!</td>', 'Very nicely done!  I''m feeling trapped already!', '2005-12-21 23:28:05.000000', NULL, 1),
(1969929, 270798, 45790, '<td valign="top">Yep, good shot. I couldn''t do it. But would this convey fear to someone without acrophobia?</td>', 'Yep, good shot. I couldn''t do it. But would this convey fear to someone without acrophobia?', '2005-12-21 23:57:38.000000', NULL, 1),
(1969932, 270597, 45790, '<td valign="top">This doesn''t convey fear, except possibly for someone already afraid of math. With all of those books, it looks like the collection of someone who loves math, so the effect is the opposite of what is intended. As a picture, the lighting is bad, and there is too much unrelated clutter in the background.</td>', 'This doesn''t convey fear, except possibly for someone already afraid of math. With all of those books, it looks like the collection of someone who loves math, so the effect is the opposite of what is intended. As a picture, the lighting is bad, and there is too much unrelated clutter in the background.', '2005-12-22 00:00:41.000000', NULL, 1),
(1969937, 270285, 45790, '<td valign="top">Unusual color change doesn''t really add to fear factor. Interesting building, and I suppose I am to fear it falling over on me. Maybe, but just doesn''t quite do it.</td>', 'Unusual color change doesn''t really add to fear factor. Interesting building, and I suppose I am to fear it falling over on me. Maybe, but just doesn''t quite do it.', '2005-12-22 00:02:53.000000', NULL, 1),
(1969938, 269583, 48245, '<td valign="top">and which phobia is this?</td>', 'and which phobia is this?', '2005-12-22 00:03:05.000000', NULL, 1),
(1969946, 270636, 45790, '<td valign="top">Verdigo? Doesn''t symbolize dizzyness or cause dizzyness to me. Mystified with what it is, though.</td>', 'Verdigo? Doesn''t symbolize dizzyness or cause dizzyness to me. Mystified with what it is, though.', '2005-12-22 00:04:20.000000', NULL, 1),
(1969948, 271248, 45790, '<td valign="top">Very good indeed!</td>', 'Very good indeed!', '2005-12-22 00:05:01.000000', NULL, 1),
(1969955, 270403, 45790, '<td valign="top">Too bright and shiney to be fearful. If she had the rope around here neck and were standing on a chair, that would be a real winner.</td>', 'Too bright and shiney to be fearful. If she had the rope around here neck and were standing on a chair, that would be a real winner.', '2005-12-22 00:07:30.000000', NULL, 1),
(1969960, 271123, 45790, '<td valign="top">And this shows fear of love exactly how?? Also poorly lit and small.</td>', 'And this shows fear of love exactly how?? Also poorly lit and small.', '2005-12-22 00:08:23.000000', NULL, 1),
(1969963, 271253, 45790, '<td valign="top">I like it. This fear is difficult to present in a photo, but the tape does it well. Like the harsh lighting as well -- it makes her pain stronger.</td>', 'I like it. This fear is difficult to present in a photo, but the tape does it well. Like the harsh lighting as well -- it makes her pain stronger.', '2005-12-22 00:10:03.000000', NULL, 1),
(1969968, 269882, 48245, '<td valign="top">while on vacation in Tokyo I saw a parking area for bikes at the train station that would have been a perfect image... several thousand bikes.</td>', 'while on vacation in Tokyo I saw a parking area for bikes at the train station that would have been a perfect image... several thousand bikes.', '2005-12-22 00:11:45.000000', NULL, 1),
(1969977, 270591, 45790, '<td valign="top">Image is too small, so detail is lost. Also I don''t see the connection with the subject -- the slide sorter and typewriter aren''t computer related. Someone with cyberphobia would be comforted with these items.  So this doesn''t "Try to make the viewer feel the emotion of the fear. "</td>', 'Image is too small, so detail is lost. Also I don''t see the connection with the subject -- the slide sorter and typewriter aren''t computer related. Someone with cyberphobia would be comforted with these items.  So this doesn''t "Try to make the viewer feel the emotion of the fear. "', '2005-12-22 00:13:57.000000', NULL, 1),
(1969984, 271113, 45790, '<td valign="top">I like the focus on the hair. I don''t know what a bogeyman is, but suspect this could be one. Creepy.</td>', 'I like the focus on the hair. I don''t know what a bogeyman is, but suspect this could be one. Creepy.', '2005-12-22 00:15:25.000000', NULL, 1),
(1969986, 270217, 30049, '<td valign="top">OK - This guy scares me too!  ;^)  Self-portrait?  He-he.  Anyway, nice lighting and composition with this.  I like the way you''ve come tight in on the face (losing the chin and hair) to emphasize the nose and eyes.  Good luck in the challenge.</td>', 'OK - This guy scares me too!  ;^)  Self-portrait?  He-he.  Anyway, nice lighting and composition with this.  I like the way you''ve come tight in on the face (losing the chin and hair) to emphasize the nose and eyes.  Good luck in the challenge.', '2005-12-22 00:15:35.000000', NULL, 1),
(1969993, 269701, 45790, '<td valign="top">Speaking of irrational fears, or did he just eat a plate of hot peppers?</td>', 'Speaking of irrational fears, or did he just eat a plate of hot peppers?', '2005-12-22 00:17:12.000000', NULL, 1),
(1970000, 270999, 45790, '<td valign="top">I though only vampires suffered from alliumphobia. This picture doesn''t show how the garlic would cause death or even bad breath. It''s only a closeup of garlic bulbs. Nothing sinister in the way it is shot.</td>', 'I though only vampires suffered from alliumphobia. This picture doesn''t show how the garlic would cause death or even bad breath. It''s only a closeup of garlic bulbs. Nothing sinister in the way it is shot.', '2005-12-22 00:20:40.000000', NULL, 1),
(1970012, 270397, 45790, '<td valign="top">When I saw this I thought "fear of mice", then I read the title and realized that this is the mouse''s view. Reminds me of an old Twilight Zone Episode, "The Invaders" where an alien space craft with little creatures crashes into the farmhouse where an old woman lives. Anyway, I''m drifting off subject. This gets a good score!</td>', 'When I saw this I thought "fear of mice", then I read the title and realized that this is the mouse''s view. Reminds me of an old Twilight Zone Episode, "The Invaders" where an alien space craft with little creatures crashes into the farmhouse where an old woman lives. Anyway, I''m drifting off subject. This gets a good score!', '2005-12-22 00:25:25.000000', NULL, 1),
(1970018, 269449, 45790, '<td valign="top">They either need to be attacking the camera (or something else that''s visible) or grouped menacingly on a clothesline to be effective. Otherwise, what''s to fear?</td>', 'They either need to be attacking the camera (or something else that''s visible) or grouped menacingly on a clothesline to be effective. Otherwise, what''s to fear?', '2005-12-22 00:28:29.000000', NULL, 1),
(1970035, 270772, 45790, '<td valign="top">"No phobia" doesn''t meet challenge description. How can you possibly "Try to make the viewer feel the emotion of the fear" if there is no fear?</td>', '"No phobia" doesn''t meet challenge description. How can you possibly "Try to make the viewer feel the emotion of the fear" if there is no fear?', '2005-12-22 00:33:02.000000', NULL, 1),
(1970106, 269282, 10261, '<td valign="top">On behalf of all of us lazy voters: your presentation would have been more viewer-friendly if your title included a brief definition of the phobia in addition to the technical word for it.<br/> <br/>I think that harsher light would have helped to give your image an added punch.</td>', 'On behalf of all of us lazy voters: your presentation would have been more viewer-friendly if your title included a brief definition of the phobia in addition to the technical word for it. I think that harsher light would have helped to give your image an added punch.', '2005-12-22 00:55:08.000000', NULL, 1),
