INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1973694, 270501, 42638, '<td valign="top">Very nice, you can feel her fear! Excellent use of space.</td>', 'Very nice, you can feel her fear! Excellent use of space.', '2005-12-23 11:04:07.000000', NULL, 1),
(1973696, 271187, 42638, '<td valign="top">Wow, looks very menacing! Nice coloring.</td>', 'Wow, looks very menacing! Nice coloring.', '2005-12-23 11:04:35.000000', NULL, 1),
(1973697, 270397, 47526, '<td valign="top">very nice.</td>', 'very nice.', '2005-12-23 11:04:37.000000', NULL, 1),
(1973701, 269313, 47852, '<td valign="top">Just back for comments...<br/>Excellent use of border to "push" the picture inward and give that drowning feeling.  Wonderful capture of action and facial expression as well.  If I had to be picky, perhaps hands doing more flailing might also have helped to convey this phobia.  Very well done.. one of my top picks for this challenge!  Good luck!</td>', 'Just back for comments...Excellent use of border to "push" the picture inward and give that drowning feeling.  Wonderful capture of action and facial expression as well.  If I had to be picky, perhaps hands doing more flailing might also have helped to convey this phobia.  Very well done.. one of my top picks for this challenge!  Good luck!', '2005-12-23 11:05:28.000000', NULL, 1),
(1973703, 271286, 47526, '<td valign="top">very creative.</td>', 'very creative.', '2005-12-23 11:06:27.000000', NULL, 1),
(1973704, 271343, 42638, '<td valign="top">Wow, Very nice. Love the "stringy-ness", makes it look even scarier(sp). The plain background is perfect choice to emphasize this.</td>', 'Wow, Very nice. Love the "stringy-ness", makes it look even scarier(sp). The plain background is perfect choice to emphasize this.', '2005-12-23 11:07:51.000000', NULL, 1),
(1973707, 269701, 42638, '<td valign="top">Very nice, How did you get this, Its fantastic. My kids are curious too although I may not share your secret with them if its too dangerous :)</td>', 'Very nice, How did you get this, Its fantastic. My kids are curious too although I may not share your secret with them if its too dangerous :)', '2005-12-23 11:09:27.000000', NULL, 1),
(1973714, 271001, 42638, '<td valign="top">Great title and image, I remember that movie. Scared the ge-bees out of me. Nice use of space.</td>', 'Great title and image, I remember that movie. Scared the ge-bees out of me. Nice use of space.', '2005-12-23 11:12:24.000000', NULL, 1),
(1973720, 271248, 42638, '<td valign="top">Very nice! Love the image and the response on his face and with his body, it really projects the phobia perfectly.</td>', 'Very nice! Love the image and the response on his face and with his body, it really projects the phobia perfectly.', '2005-12-23 11:18:58.000000', NULL, 1),
(1973732, 271113, 42638, '<td valign="top">Wow, Very nice, It even scared me when it showed on my monitor. Love the detail!</td>', 'Wow, Very nice, It even scared me when it showed on my monitor. Love the detail!', '2005-12-23 11:24:48.000000', NULL, 1),
(1973752, 269583, 49192, '<td valign="top">beautiful lighting</td>', 'beautiful lighting', '2005-12-23 11:37:08.000000', NULL, 1),
(1973952, 269955, 43148, '<td valign="top">nice to have a laugh during voting anyway!!</td>', 'nice to have a laugh during voting anyway!!', '2005-12-23 13:12:07.000000', NULL, 1),
