(1974020, 270953, 44490, '<td valign="top">Great idea arrangement, eye position, composition, exposure, and capture.  Maybe a touch more DOF would help.  I think that this is very effective and a winner.</td>', 'Great idea arrangement, eye position, composition, exposure, and capture.  Maybe a touch more DOF would help.  I think that this is very effective and a winner.', '2005-12-23 13:51:44.000000', NULL, 1),
(1974022, 269834, 44490, '<td valign="top">Good idea, lighting, color, and composition.  One of my top picks for this challenge.</td>', 'Good idea, lighting, color, and composition.  One of my top picks for this challenge.', '2005-12-23 13:53:22.000000', NULL, 1),
(1974034, 271248, 44490, '<td valign="top">Good idea, execution, and composition.  Looks a bit overprocessed, but it still works and I like it.</td>', 'Good idea, execution, and composition.  Looks a bit overprocessed, but it still works and I like it.', '2005-12-23 14:03:49.000000', NULL, 1),
(1974040, 271001, 44490, '<td valign="top">Good expression and lighting, simple, but effective.  Consider cropping just a bit more</td>', 'Good expression and lighting, simple, but effective.  Consider cropping just a bit more', '2005-12-23 14:07:09.000000', NULL, 1),
(1974053, 270405, 44490, '<td valign="top">Good expresion, composition, and capture.  An additional vertical depth element might help, as the rug/mat looks flat rather than vertical.</td>', 'Good expresion, composition, and capture.  An additional vertical depth element might help, as the rug/mat looks flat rather than vertical.', '2005-12-23 14:14:29.000000', NULL, 1),
(1974058, 270624, 44490, '<td valign="top">Great colors, especially in the drop.  Wondering if it would look better somehow tighter with one less element.</td>', 'Great colors, especially in the drop.  Wondering if it would look better somehow tighter with one less element.', '2005-12-23 14:18:49.000000', NULL, 1),
(1974061, 271076, 29011, '<td valign="top">awesome idea! One of my faves top 3 faves!</td>', 'awesome idea! One of my faves top 3 faves!', '2005-12-23 14:20:23.000000', NULL, 1),
(1974066, 270470, 49672, '<td valign="top">This is absolutely awesome...one of my favorites.  Truly captures the emotion of the phobia.  I like it dark, too (phobias are *not* bright, happy places!)</td>', 'This is absolutely awesome...one of my favorites.  Truly captures the emotion of the phobia.  I like it dark, too (phobias are *not* bright, happy places!)', '2005-12-23 14:23:41.000000', NULL, 1),
(1974067, 271248, 49672, '<td valign="top">Great capture of (melodramatic) emotion!</td>', 'Great capture of (melodramatic) emotion!', '2005-12-23 14:24:20.000000', NULL, 1),
(1974068, 271076, 49672, '<td valign="top">WOW - incredible setup and great idea.</td>', 'WOW - incredible setup and great idea.', '2005-12-23 14:24:52.000000', NULL, 1),
(1974069, 269141, 44490, '<td valign="top">Good idea, composition, focus, and you''ve managed to capture the feeling of being shut in from above.  Wish for a touch more DOF, and for removal of the shadow from the wrist, but I think that the photo is effective.</td>', 'Good idea, composition, focus, and you''ve managed to capture the feeling of being shut in from above.  Wish for a touch more DOF, and for removal of the shadow from the wrist, but I think that the photo is effective.', '2005-12-23 14:25:30.000000', NULL, 1),
(1974070, 270397, 49672, '<td valign="top">One of the funnier entries in a creepy challenge...loved it!</td>', 'One of the funnier entries in a creepy challenge...loved it!', '2005-12-23 14:25:40.000000', NULL, 1),
(1974072, 270217, 29011, '<td valign="top">This photo is one the scariest most technically well done entries of this challenge. Well done! nitpicks, just a few... the bright spot in the bottom left hand corner distracts a bit and perhaps a little crop off the top so the stare really hits one in the face ;)3<br/> <br/>edited for Spelling<br/><br/><i>Message edited by author 2007-05-02 22:07:32.</i></td>', 'This photo is one the scariest most technically well done entries of this challenge. Well done! nitpicks, just a few... the bright spot in the bottom left hand corner distracts a bit and perhaps a little crop off the top so the stare really hits one in the face ;)3 edited for Spelling', '2005-12-23 14:26:38.000000', '2007-05-02 23:07:32.000000', 1),
(1974073, 270933, 49672, '<td valign="top">What a CREEPY doll...and a great, jarring, CREEPY way to shoot it.  This is one of the best shots that doesn''t show a response from someone in the actual photo.</td>', 'What a CREEPY doll...and a great, jarring, CREEPY way to shoot it.  This is one of the best shots that doesn''t show a response from someone in the actual photo.', '2005-12-23 14:27:07.000000', NULL, 1),
