(1976465, 270974, 33400, '<td valign="top">This is a magnificent picture.  I have no idea what you''re afraid of, but it''s beautiful.</td>', 'This is a magnificent picture.  I have no idea what you''re afraid of, but it''s beautiful.', '2005-12-24 23:19:04.000000', NULL, 1),
(1976469, 270446, 33400, '<td valign="top">This fear is why I took up rapelling.  Nice visual of what I feel every time.</td>', 'This fear is why I took up rapelling.  Nice visual of what I feel every time.', '2005-12-24 23:20:36.000000', NULL, 1),
(1976472, 271076, 33400, '<td valign="top">Well this took a while to set up.  Nice take on the challenge.</td>', 'Well this took a while to set up.  Nice take on the challenge.', '2005-12-24 23:22:30.000000', NULL, 1),
